// Builds the gen-l10n ARB files from the namespaced JSON sources, then runs `flutter gen-l10n`.
//
//   l10n/<locale>/*.json   sources: { "Namespace": { "key_name": "ICU message" } }, the same
//                          shape as the Next.js boilerplate's src/locales/*.json
//   lib/l10n/arb/*.arb     generated (committed, so plain `flutter run` works)
//   lib/l10n/gen/          generated by gen-l10n (git-ignored, rebuilt by `flutter pub get`)
//
// `Namespace.key_name` becomes the getter `namespaceKeyName` (`AuthForm.email_label` →
// `context.l10n.authFormEmailLabel`). The tool fails when a locale misses a key, has an extra
// one, or uses different placeholders than English.
//
// Usage: dart run tool/l10n.dart          write the ARB files and run gen-l10n
//        dart run tool/l10n.dart --check  fail if the ARB files are out of date (CI)
import 'dart:convert';
import 'dart:io';

const _templateLocale = 'en';
const _sourceDir = 'l10n';
const _arbDir = 'lib/l10n/arb';
const _lockPath = '.dart_tool/l10n.lock';

Future<void> main(List<String> args) async {
  final check = args.contains('--check');
  final lock = await _acquireLock();
  try {
    final arbs = _buildArbs();
    if (check) {
      _checkUpToDate(arbs);
      stdout.writeln('l10n: ARB files are up to date (${arbs.length} locales).');
      return;
    }
    Directory(_arbDir).createSync(recursive: true);
    for (final entry in arbs.entries) {
      File('$_arbDir/app_${entry.key}.arb').writeAsStringSync(entry.value);
    }
    _removeStaleArbs(arbs.keys.toSet());
    final result = await Process.run('flutter', ['gen-l10n'], runInShell: true);
    stdout.write(result.stdout);
    stderr.write(result.stderr);
    if (result.exitCode != 0) {
      _fail('flutter gen-l10n failed (exit ${result.exitCode}).');
    }
    final keys = _keyCount(arbs[_templateLocale]!);
    stdout.writeln('l10n: wrote ${arbs.length} ARB files, $keys messages each.');
  } on _L10nError catch (error) {
    stderr.writeln('l10n: ${error.message}');
    exitCode = 1;
  } finally {
    lock.deleteSync();
  }
}

// ---------------------------------------------------------------------------------------------
// Sources → ARB

Map<String, String> _buildArbs() {
  final root = Directory(_sourceDir);
  if (!root.existsSync()) {
    _fail('no $_sourceDir/ directory');
  }
  final locales = root.listSync().whereType<Directory>().map((dir) => _basename(dir.path)).toList()
    ..sort();
  if (!locales.contains(_templateLocale)) {
    _fail('missing the template locale $_sourceDir/$_templateLocale');
  }

  final messages = {for (final locale in locales) locale: _readLocale(locale)};
  final template = messages[_templateLocale]!;
  final parsedTemplate = {
    for (final entry in template.entries) entry.key: _parseOrFail(entry.value, entry.key, 'en'),
  };

  final problems = <String>[];
  for (final locale in locales.where((locale) => locale != _templateLocale)) {
    final other = messages[locale]!;
    for (final key in template.keys.where((key) => !other.containsKey(key))) {
      problems.add('$locale is missing ${template[key]!.source}');
    }
    for (final key in other.keys.where((key) => !template.containsKey(key))) {
      problems.add('$locale has ${other[key]!.source}, which en does not have');
    }
    for (final key in template.keys.where(other.containsKey)) {
      final expected = parsedTemplate[key]!.placeholders.keys.toSet();
      final actual = _parseOrFail(other[key]!, key, locale).placeholders.keys.toSet();
      if (expected.length != actual.length || !expected.containsAll(actual)) {
        problems.add(
          '$locale ${other[key]!.source} uses {${actual.join(', ')}}, '
          'en uses {${expected.join(', ')}}',
        );
      }
    }
  }
  if (problems.isNotEmpty) {
    _fail('locales differ:\n  ${problems.join('\n  ')}');
  }

  return {
    for (final locale in locales)
      locale: _toArb(
        locale: locale,
        messages: messages[locale]!,
        template: locale == _templateLocale ? parsedTemplate : null,
      ),
  };
}

/// A message with where it came from, for error messages.
class _Source {
  _Source(this.message, this.source);

  final String message;
  final String source;
}

Map<String, _Source> _readLocale(String locale) {
  final files =
      Directory('$_sourceDir/$locale')
          .listSync()
          .whereType<File>()
          .where((file) => file.path.endsWith('.json'))
          .toList()
        ..sort((a, b) => a.path.compareTo(b.path));
  final result = <String, _Source>{};
  final namespaces = <String, String>{};

  for (final file in files) {
    final Object? decoded;
    try {
      decoded = jsonDecode(file.readAsStringSync());
    } on FormatException catch (error) {
      _fail('${file.path} is not valid JSON: ${error.message}');
    }
    if (decoded is! Map<String, Object?>) {
      _fail('${file.path} must be an object of namespaces');
    }
    for (final MapEntry(key: namespace, value: entries) in decoded.entries) {
      final previous = namespaces[namespace];
      if (previous != null) {
        _fail('namespace $namespace is in both $previous and ${file.path}');
      }
      namespaces[namespace] = file.path;
      if (entries is! Map<String, Object?>) {
        _fail('${file.path}: $namespace must be an object of messages');
      }
      _flatten(entries, [namespace], file.path, result);
    }
  }
  return result;
}

void _flatten(
  Map<String, Object?> entries,
  List<String> path,
  String file,
  Map<String, _Source> into,
) {
  for (final MapEntry(:key, :value) in entries.entries) {
    final keyPath = [...path, key];
    if (value is Map<String, Object?>) {
      _flatten(value, keyPath, file, into);
      continue;
    }
    if (value is! String) {
      _fail('$file: ${keyPath.join('.')} must be a string');
    }
    final getter = _getterName(keyPath);
    final source = '${keyPath.join('.')} ($file)';
    final clash = into[getter];
    if (clash != null) {
      _fail('${clash.source} and $source both become the getter $getter');
    }
    into[getter] = _Source(value, source);
  }
}

final _identifier = RegExp(r'^[a-z][A-Za-z0-9]*$');

/// `['AuthForm', 'email_label']` → `authFormEmailLabel`.
String _getterName(List<String> keyPath) {
  final words = keyPath.expand((part) => part.split(RegExp('[_.-]'))).where((w) => w.isNotEmpty);
  final buffer = StringBuffer();
  for (final (index, word) in words.indexed) {
    buffer.write(
      index == 0
          ? word[0].toLowerCase() + word.substring(1)
          : word[0].toUpperCase() + word.substring(1),
    );
  }
  final name = buffer.toString();
  if (!_identifier.hasMatch(name)) {
    _fail('${keyPath.join('.')} does not make a valid getter name ($name)');
  }
  return name;
}

_Message _parseOrFail(_Source source, String key, String locale) {
  try {
    return _Message.parse(source.message);
  } on FormatException catch (error) {
    _fail('$locale ${source.source}: ${error.message}\n  "${source.message}"');
  }
}

String _toArb({
  required String locale,
  required Map<String, _Source> messages,
  required Map<String, _Message>? template,
}) {
  final arb = <String, Object?>{'@@locale': locale};
  final keys = messages.keys.toList()..sort();
  for (final key in keys) {
    final parsed = _parseOrFail(messages[key]!, key, locale);
    arb[key] = parsed.toGenL10n();
    if (template != null) {
      final placeholders = template[key]!.placeholders;
      arb['@$key'] = {
        if (placeholders.isNotEmpty)
          'placeholders': {
            for (final MapEntry(key: name, value: type) in placeholders.entries)
              name: type.toArbMetadata(),
          },
      };
    }
  }
  return '${const JsonEncoder.withIndent('  ').convert(arb)}\n';
}

void _checkUpToDate(Map<String, String> arbs) {
  final stale = [
    for (final MapEntry(key: locale, value: content) in arbs.entries)
      if (!File('$_arbDir/app_$locale.arb').existsSync() ||
          File('$_arbDir/app_$locale.arb').readAsStringSync() != content)
        '$_arbDir/app_$locale.arb',
  ];
  if (stale.isNotEmpty) {
    _fail('out of date: ${stale.join(', ')}. Run `make l10n` and commit the result.');
  }
}

void _removeStaleArbs(Set<String> locales) {
  for (final file in Directory(_arbDir).listSync().whereType<File>()) {
    final match = RegExp(r'app_(\w+)\.arb$').firstMatch(file.path);
    if (match != null && !locales.contains(match.group(1))) {
      file.deleteSync();
    }
  }
}

int _keyCount(String arb) =>
    (jsonDecode(arb) as Map<String, Object?>).keys.where((k) => !k.startsWith('@')).length;

// ---------------------------------------------------------------------------------------------
// ICU messages (the subset next-intl and gen-l10n share, plus `#` and `{x, number, style}`).

sealed class _Node {}

class _Text extends _Node {
  _Text(this.text);

  final String text;
}

class _Pound extends _Node {}

class _Argument extends _Node {
  _Argument({required this.name, this.kind, this.style, this.branches = const {}});

  final String name;

  /// null for `{name}`, else `plural`, `select` or `number`.
  final String? kind;
  final String? style;
  final Map<String, List<_Node>> branches;
}

enum _PlaceholderKind { string, integer, number }

class _Placeholder {
  _Placeholder(this.kind, [this.numberStyle]);

  final _PlaceholderKind kind;
  final String? numberStyle;

  Map<String, Object?> toArbMetadata() => switch (kind) {
    _PlaceholderKind.string => {'type': 'String'},
    _PlaceholderKind.integer => {'type': 'int'},
    _PlaceholderKind.number => _numberMetadata(numberStyle),
  };

  static Map<String, Object?> _numberMetadata(String? style) {
    if (style == 'percent') {
      return {'type': 'num', 'format': 'percentPattern'};
    }
    final digits = style == null ? null : RegExp(r'^::\.(0+)$').firstMatch(style)?.group(1);
    if (digits != null) {
      return {
        'type': 'num',
        'format': 'decimalPatternDigits',
        'optionalParameters': {'decimalDigits': digits.length},
      };
    }
    return {'type': 'num', 'format': 'decimalPattern'};
  }
}

class _Message {
  _Message(this.nodes);

  factory _Message.parse(String source) {
    final parser = _Parser(source);
    final nodes = parser.parseNodes(inPlural: false);
    if (!parser.done) {
      throw FormatException('unexpected "}" at ${parser.position}');
    }
    return _Message(nodes);
  }

  final List<_Node> nodes;

  /// Placeholder names with their types, in order of first use.
  Map<String, _Placeholder> get placeholders {
    final result = <String, _Placeholder>{};
    void visit(List<_Node> nodes) {
      for (final node in nodes) {
        if (node is! _Argument) {
          continue;
        }
        final placeholder = switch (node.kind) {
          'plural' => _Placeholder(_PlaceholderKind.integer),
          'number' => _Placeholder(_PlaceholderKind.number, node.style),
          _ => _Placeholder(_PlaceholderKind.string),
        };
        final existing = result[node.name];
        // A plural count stays an int even where it is also printed as plain text.
        if (existing == null || existing.kind == _PlaceholderKind.string) {
          result[node.name] = placeholder;
        }
        node.branches.values.forEach(visit);
      }
    }

    visit(nodes);
    return result;
  }

  String toGenL10n() => _serialize(nodes, null);

  static String _serialize(List<_Node> nodes, String? pluralName) {
    final buffer = StringBuffer();
    for (final node in nodes) {
      switch (node) {
        case _Text(:final text):
          buffer.write(text);
        case _Pound():
          buffer.write(pluralName == null ? '#' : '{$pluralName}');
        case _Argument(:final name, kind: null || 'number'):
          buffer.write('{$name}');
        case _Argument(:final name, :final kind, :final branches):
          buffer.write('{$name, $kind,');
          for (final MapEntry(key: selector, value: branch) in branches.entries) {
            final inner = _serialize(branch, kind == 'plural' ? name : pluralName);
            buffer.write(' $selector{$inner}');
          }
          buffer.write('}');
      }
    }
    return buffer.toString();
  }
}

class _Parser {
  _Parser(this.source);

  final String source;
  int position = 0;

  bool get done => position >= source.length;

  List<_Node> parseNodes({required bool inPlural}) {
    final nodes = <_Node>[];
    final text = StringBuffer();
    void flush() {
      if (text.isNotEmpty) {
        nodes.add(_Text(text.toString()));
        text.clear();
      }
    }

    while (!done) {
      final char = source[position];
      if (char == '}') {
        break;
      }
      if (char == '{') {
        flush();
        nodes.add(_parseArgument());
        continue;
      }
      if (char == '#' && inPlural) {
        flush();
        nodes.add(_Pound());
        position++;
        continue;
      }
      text.write(char);
      position++;
    }
    flush();
    return nodes;
  }

  _Argument _parseArgument() {
    _expect('{');
    final name = _readUntil({',', '}'}).trim();
    if (!RegExp(r'^[A-Za-z_][A-Za-z0-9_]*$').hasMatch(name)) {
      throw FormatException('invalid placeholder name "$name" at $position');
    }
    if (_peek() == '}') {
      position++;
      return _Argument(name: name);
    }
    _expect(',');
    final kind = _readUntil({',', '}'}).trim();
    switch (kind) {
      case 'number':
        String? style;
        if (_peek() == ',') {
          position++;
          style = _readUntil({'}'}).trim();
        }
        _expect('}');
        return _Argument(name: name, kind: kind, style: style);
      case 'plural' || 'select':
        _expect(',');
        final branches = <String, List<_Node>>{};
        while (true) {
          _skipSpaces();
          if (_peek() == '}') {
            position++;
            break;
          }
          final selector = _readUntil({'{'}).trim();
          if (selector.isEmpty || selector.contains(RegExp(r'\s'))) {
            throw FormatException('invalid $kind selector "$selector" at $position');
          }
          _expect('{');
          branches[selector] = parseNodes(inPlural: kind == 'plural');
          _expect('}');
        }
        if (!branches.containsKey('other')) {
          throw FormatException('$kind for "$name" needs an "other" branch');
        }
        return _Argument(name: name, kind: kind, branches: branches);
      default:
        throw FormatException('unsupported argument type "$kind" for "$name"');
    }
  }

  String? _peek() => done ? null : source[position];

  void _skipSpaces() {
    while (!done && source[position].trim().isEmpty) {
      position++;
    }
  }

  void _expect(String char) {
    _skipSpaces();
    if (_peek() != char) {
      throw FormatException('expected "$char" at $position');
    }
    position++;
  }

  String _readUntil(Set<String> stops) {
    final start = position;
    while (!done && !stops.contains(source[position])) {
      position++;
    }
    if (done) {
      throw FormatException('unclosed "{" starting near $start');
    }
    return source.substring(start, position);
  }
}

// ---------------------------------------------------------------------------------------------
// Helpers

class _L10nError implements Exception {
  _L10nError(this.message);

  final String message;
}

Never _fail(String message) => throw _L10nError(message);

String _basename(String path) => path.split(Platform.pathSeparator).last;

/// Several agents or terminals may run this at once; let them take turns.
Future<File> _acquireLock() async {
  final lock = File(_lockPath);
  Directory('.dart_tool').createSync(recursive: true);
  for (var attempt = 0; attempt < 600; attempt++) {
    try {
      lock.createSync(exclusive: true);
      return lock;
    } on FileSystemException {
      final age = DateTime.now().difference(lock.statSync().modified);
      if (age > const Duration(minutes: 2)) {
        lock.deleteSync();
        continue;
      }
      await Future<void>.delayed(const Duration(milliseconds: 200));
    }
  }
  _fail('timed out waiting for $_lockPath');
}
